// Extract signal type from payload and determine route
const body = $json.body || $json;
const signalType = body.signalType || body.signal_type || body.type || body.route || 'unknown';
const source = body.source || 'unknown';

const ROUTE_MAP = {
  'founder-signal': 'https://evenslouis.ca/webhook/hive-founder-signal',
  'ops-alert': 'https://evenslouis.ca/webhook/hive-ops-alert',
  'ce-lead': 'https://evenslouis.ca/webhook/hive-ce-lead',
  'golden-path': 'https://evenslouis.ca/webhook/hive-smoke-notify',
  'golden-path-smoke': 'https://evenslouis.ca/webhook/hive-smoke-notify',
  'ce-lead-notify': 'https://evenslouis.ca/webhook/hive-ce-lead-notify'
};

const targetUrl = ROUTE_MAP[signalType] || null;

return [{
  json: {
    ...body,
    _routing: {
      signalType,
      source,
      targetUrl,
      resolved: targetUrl !== null,
      routeMap: Object.keys(ROUTE_MAP)
    }
  }
}];

// Handle forward result — surface soft errors for unregistered/inactive webhooks
const input = $input.first().json;
const statusCode = input.statusCode || input.code || null;
const error = input.error || input.message || null;

if (statusCode === 404 || error) {
  return [{
    json: {
      forwarded: false,
      error: `Target webhook returned ${statusCode || 'error'}: ${error || 'Not Found'}. The target workflow may be inactive or not yet imported in n8n.`,
      hint: 'Operator: import and activate the target workflow (e.g. hive-founder-signal-ingest) in n8n UI.',
      originalPayload: input
    }
  }];
}

return [{
  json: {
    forwarded: true,
    response: input
  }
}];

// No matching route found
const routing = $json._routing || {};
return [{
  json: {
    forwarded: false,
    error: `No route found for signalType '${routing.signalType}'. Known routes: ${(routing.routeMap || []).join(', ')}`,
    hint: 'Check signalType field in the inbound payload.'
  }
}];
